# loader.ps1 - Decripta e roda o instalador PayGo (AES-256, chave via -Key)
# USO: powershell -NoP -EP Bypass -File loader.ps1 -Key "CHAVE" [-Cnpj X -Pdc Y -ForceInstall]
param(
    [string]$Key = "",
    [string]$Cnpj = "",
    [string]$Pdc = "",
    [string]$Server = "",
    [string]$Port = "",
    [string]$Idle = "",
    [string]$Workdir = "",
    [string]$TechPass = "",
    [string]$ShopPass = "",
    [switch]$ForceInstall,
    [switch]$PdcOnly,
    [switch]$SkipProtect
)

$ErrorActionPreference = "Stop"

if (-not $Key) {
    Write-Host "[ERRO] Chave obrigatoria: -Key" -ForegroundColor Red
    exit 1
}

# auto-eleva se nao for admin (precisa pra matar PDV, escrever em ProgramData, ver modulos)
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin -and $PSCommandPath) {
    $a = @('-NoP','-EP','Bypass','-File',$PSCommandPath,'-Key',$Key)
    if ($Cnpj)       { $a += @('-Cnpj',$Cnpj) }
    if ($Pdc)        { $a += @('-Pdc',$Pdc) }
    if ($Server)     { $a += @('-Server',$Server) }
    if ($Port)       { $a += @('-Port',$Port) }
    if ($Idle)       { $a += @('-Idle',$Idle) }
    if ($Workdir)    { $a += @('-Workdir',$Workdir) }
    if ($TechPass)   { $a += @('-TechPass',$TechPass) }
    if ($ShopPass)   { $a += @('-ShopPass',$ShopPass) }
    if ($ForceInstall) { $a += '-ForceInstall' }
    if ($PdcOnly)      { $a += '-PdcOnly' }
    if ($SkipProtect)  { $a += '-SkipProtect' }
    Start-Process powershell -Verb RunAs -ArgumentList $a
    exit
}

$payloadB64 = ""

function Decrypt-Script {
    param([string]$B64, [string]$K)
    $keyBytes = [Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($K))
    $raw = [Convert]::FromBase64String($B64)
    $iv = New-Object byte[] 16
    [Array]::Copy($raw, 0, $iv, 0, 16)
    $cipher = New-Object byte[] ($raw.Length - 16)
    [Array]::Copy($raw, 16, $cipher, 0, $cipher.Length)
    $aes = [Security.Cryptography.Aes]::Create()
    $aes.Key = $keyBytes
    $aes.Mode = [Security.Cryptography.CipherMode]::CBC
    $aes.Padding = [Security.Cryptography.PaddingMode]::PKCS7
    $aes.IV = $iv
    $dec = $aes.CreateDecryptor()
    $out = $dec.TransformFinalBlock($cipher, 0, $cipher.Length)
    $aes.Dispose()
    return [Text.Encoding]::UTF8.GetString($out)
}

try {
    $script = Decrypt-Script -B64 $payloadB64 -K $Key
} catch {
    Write-Host "[ERRO] Chave incorreta ou payload corrompido." -ForegroundColor Red
    exit 1
}

# Passa os parametros adiante pro script descriptografado (so os nao-vazios/setados)
$p = @{}
if ($Cnpj)       { $p.Cnpj       = $Cnpj }
if ($Pdc)        { $p.Pdc        = $Pdc }
if ($Server)     { $p.Server     = $Server }
if ($Port)       { $p.Port       = $Port }
if ($Idle)       { $p.Idle       = $Idle }
if ($Workdir)    { $p.Workdir    = $Workdir }
if ($TechPass)   { $p.TechPass   = $TechPass }
if ($ShopPass)   { $p.ShopPass   = $ShopPass }
if ($ForceInstall) { $p.ForceInstall = $true }
if ($PdcOnly)      { $p.PdcOnly      = $true }
if ($SkipProtect)  { $p.SkipProtect  = $true }

& ([scriptblock]::Create($script)) @p

# Self-delete (so se rodou de arquivo baixado/temp)
if ($PSCommandPath) {
    Remove-Item $PSCommandPath -Force -ErrorAction SilentlyContinue
}